INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=11 AND status='published'),'about','About Veterinary Medicine',NULL,'<p>Veterinary Medicine focuses on diagnosing and treating illness in animals. It sits within Health, Medicine &amp; Veterinary Studies and is offered by universities in the UK, US, Canada, Australia, Germany, Ireland and elsewhere.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=11 AND status='published') AND name='Veterinary Medicine'));
