INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=11 AND status='published'),'about','About Veterinary Bioscience',NULL,'<p>Veterinary Bioscience focuses on biological science for veterinary medicine. It sits within Health, Medicine &amp; Veterinary Studies and is offered by universities in the UK, US, Canada, Australia, Germany, Ireland and elsewhere.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=11 AND status='published') AND name='Veterinary Bioscience'));
INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=11 AND status='published'),'why','Why study Veterinary Bioscience?',NULL,'<p>Veterinary Bioscience builds specialist skills in biological science for veterinary medicine. Typical graduate roles include research scientist, veterinary scientist, lab technician. Demand, pay and visa options vary by country, so compare destinations before you apply.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=11 AND status='published') AND name='Veterinary Bioscience'));
