INSERT INTO subject_sections (id,subject_id,section,title,subtitle,body,status,display_order,specialization_id) VALUES (gen_random_uuid(),(SELECT id FROM subjects WHERE display_order=15 AND status='published'),'about','About Neuroscience',NULL,'<p>Neuroscience focuses on the nervous system and the brain. It sits within Psychology &amp; Behavioural Sciences and is offered by universities in the UK, US, Canada, Australia, Germany, Ireland and elsewhere.</p>','published',1,(SELECT id FROM specializations WHERE subject_id=(SELECT id FROM subjects WHERE display_order=15 AND status='published') AND name='Neuroscience'));
