UPDATE subjects SET about_title='About Psychology & Behavioural Sciences', about_body='<p>Psychology and Behavioural Sciences studies the mind, behaviour and mental processes. Areas include clinical, counselling, forensic, educational, health, organisational, developmental and cognitive psychology, plus neuroscience and behavioural science.</p><p>Courses combine theory, research methods, statistics and practical work.</p><p>Becoming a practising psychologist usually requires further professional training and registration (for example a doctorate or accredited master''s), which differs by country. A psychology degree abroad does not automatically qualify you to practise.</p>', why_title='Why study Psychology & Behavioural Sciences?', why_body='<p><strong>Versatile degree.</strong> Understanding behaviour is valuable in HR, marketing, UX, education, healthcare and policy.</p><p><strong>Research and data skills.</strong> Methods and statistics training supports careers in data and insights.</p><p><strong>Pathways to professional practice.</strong> Accredited degrees lead to clinical, counselling, forensic and occupational routes.</p><p><strong>Growing awareness.</strong> Demand for mental-health support and behavioural insight is rising.</p>' WHERE id=(SELECT id FROM subjects WHERE display_order=15 AND status='published');
UPDATE subject_study_levels SET about_title='About Foundation in Psychology & Behavioural Sciences', about_body='<p>A Foundation in Psychology &amp; Behavioural Sciences. A one-year preparatory programme that builds subject knowledge and English skills before a bachelor''s degree.</p><p>Usually for students who have finished secondary school but don''t yet meet direct-entry requirements for a bachelor''s.</p>', why_title='Why choose a Foundation in Psychology & Behavioural Sciences?', why_body='<p>Foundation study in Psychology &amp; Behavioural Sciences lets you build the skills and credentials employers in this field look for. A one-year preparatory programme that builds subject knowledge and English skills before a bachelor''s degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=15 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='foundation');
UPDATE subject_study_levels SET about_title='About Pathway in Psychology & Behavioural Sciences', about_body='<p>A Pathway in Psychology &amp; Behavioural Sciences. A programme run with a partner university that leads into the first or second year of a degree.</p><p>Usually for students who need extra academic or English preparation, or want guaranteed progression to a partner university.</p>', why_title='Why choose a Pathway in Psychology & Behavioural Sciences?', why_body='<p>Pathway study in Psychology &amp; Behavioural Sciences lets you build the skills and credentials employers in this field look for. A programme run with a partner university that leads into the first or second year of a degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=15 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='pathway');
UPDATE subject_study_levels SET about_title='About Diploma in Psychology & Behavioural Sciences', about_body='<p>A Diploma in Psychology &amp; Behavioural Sciences. Practical, career-focused study that often counts toward the second year of a bachelor''s degree.</p><p>Usually for students who want job-focused training or a flexible route into a degree.</p>', why_title='Why choose a Diploma in Psychology & Behavioural Sciences?', why_body='<p>Diploma study in Psychology &amp; Behavioural Sciences lets you build the skills and credentials employers in this field look for. Practical, career-focused study that often counts toward the second year of a bachelor''s degree.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=15 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='diploma');
UPDATE subject_study_levels SET about_title='About Bachelor''s in Psychology & Behavioural Sciences', about_body='<p>A Bachelor''s in Psychology &amp; Behavioural Sciences. Your first university degree, typically 3–4 years.</p><p>Usually requires completed secondary school with strong results, plus English proof (for example IELTS or TOEFL).</p>', why_title='Why choose a Bachelor''s in Psychology & Behavioural Sciences?', why_body='<p>Bachelor''s study in Psychology &amp; Behavioural Sciences lets you build the skills and credentials employers in this field look for. Your first university degree, typically 3–4 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=15 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='bachelors');
UPDATE subject_study_levels SET about_title='About Master''s in Psychology & Behavioural Sciences', about_body='<p>A Master''s in Psychology &amp; Behavioural Sciences. Specialist or career-change study after a bachelor''s degree, typically 1–2 years.</p><p>Usually requires a bachelor''s degree with good grades, English proof, and sometimes work experience or tests such as GRE or GMAT.</p>', why_title='Why choose a Master''s in Psychology & Behavioural Sciences?', why_body='<p>Master''s study in Psychology &amp; Behavioural Sciences lets you build the skills and credentials employers in this field look for. Specialist or career-change study after a bachelor''s degree, typically 1–2 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=15 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='masters');
UPDATE subject_study_levels SET about_title='About MBA in Psychology & Behavioural Sciences', about_body='<p>A MBA in Psychology &amp; Behavioural Sciences. A master''s in business and management, usually for people with work experience.</p><p>Usually requires a bachelor''s degree, 2–5 years of work experience, GMAT/GRE (some schools waive) and English proof.</p>', why_title='Why choose a MBA in Psychology & Behavioural Sciences?', why_body='<p>MBA study in Psychology &amp; Behavioural Sciences lets you build the skills and credentials employers in this field look for. A master''s in business and management, usually for people with work experience.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=15 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='mba');
UPDATE subject_study_levels SET about_title='About PhD in Psychology & Behavioural Sciences', about_body='<p>A PhD in Psychology &amp; Behavioural Sciences. Original research under a supervisor, typically 3–5 years.</p><p>Usually requires a master''s degree (or an exceptional bachelor''s), a research proposal and supervisor agreement.</p>', why_title='Why choose a PhD in Psychology & Behavioural Sciences?', why_body='<p>PhD study in Psychology &amp; Behavioural Sciences lets you build the skills and credentials employers in this field look for. Original research under a supervisor, typically 3–5 years.</p><p>Costs, intakes and work rights vary by country, so compare destinations before applying.</p>' WHERE subject_id=(SELECT id FROM subjects WHERE display_order=15 AND status='published') AND study_level_id=(SELECT id FROM study_levels WHERE slug='phd');
COMMIT;